create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', profile_image text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.business_profiles (id uuid primary key default gen_random_uuid(), owner_id uuid not null unique references auth.users(id) on delete cascade, business_name text not null default '', business_type text not null default 'Service Provider', industry text not null default '', country text not null default '', city text not null default '', website text not null default '', phone text not null default '', business_description text not null default '', products jsonb not null default '[]'::jsonb, services jsonb not null default '[]'::jsonb, capabilities jsonb not null default '[]'::jsonb, offers jsonb not null default '[]'::jsonb, needs jsonb not null default '[]'::jsonb, target_customers jsonb not null default '[]'::jsonb, target_suppliers jsonb not null default '[]'::jsonb, target_manufacturers jsonb not null default '[]'::jsonb, target_partners jsonb not null default '[]'::jsonb, target_markets jsonb not null default '[]'::jsonb, business_goals jsonb not null default '[]'::jsonb, business_keywords jsonb not null default '[]'::jsonb, onboarding_step text not null default 'start', onboarding_completed boolean not null default false, is_verified boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.connections (id uuid primary key default gen_random_uuid(), requester_id uuid not null references auth.users(id) on delete cascade, recipient_id uuid not null references auth.users(id) on delete cascade, message text, status text not null default 'pending' check (status in ('pending','accepted','rejected','removed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (requester_id <> recipient_id), unique (requester_id, recipient_id));
create table public.conversations (id uuid primary key default gen_random_uuid(), user_a uuid not null references auth.users(id) on delete cascade, user_b uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), last_message_at timestamptz, check (user_a <> user_b), check (user_a < user_b), unique (user_a, user_b));
create table public.messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, sender_id uuid not null references auth.users(id) on delete cascade, content text not null check (char_length(content) between 1 and 10000), is_read boolean not null default false, created_at timestamptz not null default now());
create table public.opportunities (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, title text not null, category text not null default '', description text not null default '', what_they_need text not null default '', country text not null default '', city text not null default '', quantity text, budget text, timeline text, requirements text, status text not null default 'open' check (status in ('open','in_progress','closed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.opportunity_responses (id uuid primary key default gen_random_uuid(), opportunity_id uuid not null references public.opportunities(id) on delete cascade, responder_id uuid not null references auth.users(id) on delete cascade, pitch text not null, budget_quote text, created_at timestamptz not null default now(), unique (opportunity_id, responder_id));
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, type text not null, title text not null, message text not null default '', link text, is_read boolean not null default false, created_at timestamptz not null default now());
create index business_profiles_discovery_idx on public.business_profiles (industry, country, city, business_type);
create index connections_recipient_status_idx on public.connections (recipient_id, status);
create index messages_conversation_created_idx on public.messages (conversation_id, created_at desc);
create index opportunities_status_created_idx on public.opportunities (status, created_at desc);
create index notifications_user_created_idx on public.notifications (user_id, created_at desc);
alter table public.profiles enable row level security;
alter table public.business_profiles enable row level security;
alter table public.connections enable row level security;
alter table public.conversations enable row level security;
alter table public.messages enable row level security;
alter table public.opportunities enable row level security;
alter table public.opportunity_responses enable row level security;
alter table public.notifications enable row level security;
